<!--
 * 应用管理页面 — 应用注册的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\app\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 应用（列表页）
 * <p>消费后端契约 AppInfoController（src/api/appInfo.ts，auto-generated by bash/gen-contract.py）的应用列表页：
 * 分页查询 page、编辑/删除（remove）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/appInfo';
import type { AppInfoPageQuery, AppInfoVO, PageQuery } from '#/api/models';

import AppForm from './app-form.vue';

defineOptions({ name: 'AppManagement' });

/** 行类型：真实契约 AppInfoVO（字段以 models.ts 为准） */
type AppRow = AppInfoVO;

/** 分页查询参数：契约 AppInfoPageQuery + 通用分页字段（models.ts PageQuery） */
type AppPageQueryParams = AppInfoPageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

const gridOptions: VxeTableGridOptions<AppRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'appCode', title: '应用编码', width: 140 },
    { field: 'appName', title: '应用名称', width: 160 },
    { field: 'appKey', title: '应用 Key', width: 180 },
    { field: 'redirectUrl', title: '回调地址', width: 200 },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const app = row as AppRow;
          return h(
            ElTag,
            { type: isEnabled(app.status) ? 'success' : 'info' },
            () => (isEnabled(app.status) ? '启用' : '禁用'),
          );
        },
      },
    },
    { field: 'description', title: '描述', width: 180 },
    {
      field: 'action',
      title: '操作',
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const app = row as AppRow;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(app) }, () => '编辑'),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(app) }, () => '删除'),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: AppPageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'appName', title: '应用名称', itemRender: { name: 'Input', props: { placeholder: '应用名称' } } },
      { field: 'status', title: '状态', itemRender: { name: 'Input', props: { placeholder: '状态（1/0）' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [AppFormModal, appFormApi] = useYDSZModal({ connectedComponent: AppForm });

function handleAdd() {
  appFormApi.open();
}

function handleEdit(row: AppRow) {
  appFormApi.setData({ record: row });
  appFormApi.open();
}

async function handleDelete(row: AppRow) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(`确定删除「${row.appName ?? row.appCode ?? ''}」吗？`, '删除确认', { type: 'warning' });
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="应用注册">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增</ElButton>
      </template>
    </Grid>
    <AppFormModal @success="gridApi.query()" />
  </Page>
</template>